svg.script:
window.__svgAufblitzen = 0;
window.__svgVerborgen = 0;
(function schritt() {
  setTimeout(function () {
    var wurzel = document.documentElement;
    if (wurzel.getAttribute('data-veil-seite') === 'aus') return;
    var bilder = document.querySelectorAll('image');
    for (var i = 0; i < bilder.length; i++) {
      if (bilder[i].getAttribute('data-veil') !== null) continue;
      if (getComputedStyle(bilder[i]).opacity === '0') window.__svgVerborgen++;
      else window.__svgAufblitzen++;
    }
  }, 0);
  requestAnimationFrame(schritt);
})();
